INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64184239', 64184239, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Data Engineer Pengembangan Produk dan Layanan Februari 1 #1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 10175000, 'January 2026', 'APBD', 1, 1, '1 Orang x 1 Bulan', '1. Membantu proses Extract, Transform, Load (ETL/ELT) sesuai arahan Senior Data Engineer. 2. Melakukan pembersihan data tingkat lanjut (data cleaning) serta menyiapkan dataset yang siap digunakan untuk analisis. 3. Pengelolaan database, termasuk pemantauan performa dasar, pengecekan konsistensi data, dan penyelarasan struktur tabel. 4. Merancang, membangun, dan mengelola pipeline data (ETL/ELT) yang efisien, scalable, dan otomatis. 5. Mengelola database relasional dan non-relasional, termasuk optimalisasi performa query dan perancangan skema data. 6. Mengembangkan integrasi data lintas sistem dan API untuk kebutuhan platform analitik, operasional, atau aplikasi layanan publik. 7. Melakukan transformasi data tingkat lanjut untuk memastikan data siap pakai dan sesuai standar governance. 8. Mengelola data warehouse atau data lake, termasuk partisi, versioning, dan pengaturan storage. 9. Mendukung Data Analyst dan Data Scientist dalam penyediaan dataset, fitur, dan struktur data yang dibutuhkan. 10. Mengembangkan dokumentasi teknis terkait arsitektur data, pipeline, API, dan tata kelola data.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1416179);
