INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64184031', 64184031, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Data Analyst Pengembangan Produk dan Layanan Februari 3 #3', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 10175000, 'January 2026', 'APBD', 1, 1, '1 Orang x 1 Bulan', '1. Melaksanakan proses pengolahan data tingkat lanjut, termasuk transformasi, agregasi, dan eksplorasi data (EDA). 2. Menyusun analisis kuantitatif dan kualitatif berdasarkan metodologi statistik yang relevan. 3. Membuat visualisasi data interaktif dan informatif menggunakan tools seperti Tableau, Looker Studio dan lainnya. 4. Mengembangkan query database (SQL) untuk kebutuhan ekstraksi data secara efisien dan akurat. 5. Menyusun laporan analisis secara komprehensif, termasuk insight dan rekomendasi berbasis data. 6. Melakukan verifikasi kualitas data (data quality assurance) dan validasi hasil analisis. 7. Berkoordinasi dengan tim lintas divisi dan perangkat daerah untuk memahami kebutuhan analitis dan menerjemahkannya ke dalam spesifikasi analisis data. 8. Mengelola dan memelihara dokumentasi data, pipeline analisis, dan standar kerja teknis. 9. Memberikan supervisi dasar kepada Junior Data Analyst saat diperlukan.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1418771);
