INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64185350', 64185350, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Technical Writer Pengembangan Produk dan Layanan Februari 3 #4', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 10175000, 'January 2026', 'APBD', 1, 1, '1 Orang x 1 Bulan', '1. Menyusun dokumentasi pengembangan sistem yang mencakup pemahaman mendalam terhadap tahapan pengembangan, serta menyajikannya secara jelas dan terstruktur; 2. Membuat dokumentasi teknis, seperti Functional Specification Document, Business Requirements Document, maupun Software Requirements Specification, serta menyajikannya dengan detail dan jelas untuk dijadikan panduan oleh tim pengembangan dan pemangku kepentingan; 3. Membuat Manual Book/Manual Operation dari suatu aplikasi atau sistem yang menyajikan panduan pengguna yang jelas dan terstruktur untuk mendukung pemahaman dan penggunaan yang efektif; 4. Berpartisipasi dari awal hingga akhir dalam proses pengembangan sistem bersama tim teknis, serta terlibat aktif dalam berbagai pertemuan/sesi briefing untuk mencapai pemahaman penuh terhadap produk atau proyek yang sedang dikembangkan; 5. Memahami informasi teknis yang kompleks dan mampu mengkomunikasikannya kepada orang-orang dengan berbagai macam latar belakang, serta dapat menyederhanakan bahasa teknis agar dapat dimengerti oleh audiens yang mungkin tidak memiliki pemahaman teknis yang mendalam, dan 6. Menyajikan dokumentasi teknis sesuai dengan standarisasi dan kebutuhan, serta memastikan bahwa dokumen yang dihasilkan memenuhi persyaratan dan dapat digunakan sebagai panduan yang akurat dan berguna bagi seluruh tim pengembangan.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1419767);
